from .netact import CmOperations


class cm(object):
    """
    This library Pilot Netact Configuration Management API
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.cm = CmOperations()

    def connect_to(self, hostname, username, password=None):
        """
        To run the command log in to a virtual machine, where the was -<nodename> service is running.
        For more information, see locating the right virtual machine for a service administrating
        NetAct Virtual Infrastructure

        :param hostname: str: IP Address of NetAct VM administrating SWM API
        :param username: str: username for ssh session
        :param password: str: password for ssh session, By default fixed to None

        :return: ssh session
        """
        return self.cm.connect_to(hostname, username, password)

    def disconnect(self):
        """
        Close current connection.

        :return: None
        """
        return self.cm.disconnect()

    def upload(self, bts_dist_name, backup=False):
        """
        Upload Network Element configuration data and storing it as actual configuration to the NetAct Configurator
        database.

        :param str bts_dist_name: MRBTS ID e.g MRBTS-329
        :param bool backup: backup existing configuration file in NetAct False (by default)

        :return: state of upload operation
        """
        return self.cm.upload(bts_dist_name, backup)

    def export_plan(self, dist_name, ui_values=True):
        """
        Export Actual Configuration in NetAct for specified MO and save configuration on local machine


        :param str dist_name: MO distinguish name e.g MRBTS-329, MRBTS-345/NRBTS-5
        :param bool ui_values: specifies if the file using UI values with parameters is imported
                                or exported. true(default)

        :return: path to exported file on local machine
        """
        return self.cm.export_plan(dist_name, ui_values)

    def import_plan(self, path_to_file, planname, ui_values=False, objectoperationdefinedinimport=False):
        """
        import plan given as path_to_file as NetAct plan name, plan is stored to NetAct import directory.

        :param str path_to_file: path to plan file
        :param str planname: specifies a name of plan
        :param str ui_values: specifies if the file using UI values with parameters is imported
                            or exported. false (default)
        :param str objectoperationdefinedinimport: if true and operation is missing from import file, object is not
                            imported. If false, object operation is set based on object existence in NetAct database.
                            default value : false

        :return: state of operation
        """
        return self.cm.import_plan(path_to_file, planname, ui_values, objectoperationdefinedinimport)

    def provision(self, plan_name, provisioning_operation='activate', create_backup=True):
        """
        provision plan to the network.

        :param str plan_name: specifies a plan name

        :return: state of provision operation
        """
        return self.cm.provision(plan_name, provisioning_operation, create_backup)

    def validate(self, dist_name, plan_name):
        """
        validate the plan in Netact.

        :param str dist_name: MRBTS_ID e.g MRBTS-329
        :param str plan_name: specifies a plan name

        :return: state of validation operation
        """
        return self.cm.validate(dist_name, plan_name)

    def remove_plan(self, plan_name):
        """
        delete plan from Configurator Database.

        :param str plan_name: specifies a plan name


        :return: state of operation
        """
        return self.cm.remove_plan(plan_name)

    def compare_plans(self, plan_name, delta_plan_name):
        """
        Make delta from given plan name and save it as given delta_plan_name.

        :param str plan_name: specifies plan name
        :param str delta_plan_name: specifies delta plan name


        :return: state of operation
        """
        return self.cm.compare_plans(plan_name, delta_plan_name)
